export interface SupplierProduct {
  supplier_product_id: string;
  supplier_id: string;
  product_id: string;
  price: number;
}

// Payload used when creating a supplier-product price.
// supplier_product_id is generated by the C# controller.
export type SupplierProductInput = Omit<SupplierProduct, "supplier_product_id">;

// Read model returned by GET /api/SupplierProducts.
export interface SupplierProductDto {
  supplier_product_id: string;
  supplier_id: string;
  supplier_name: string;
  product_id: string;
  product_name: string;
  price: number;
  img: string;
}

const API_URL = "https://localhost:7278/api/supplierproducts";

async function request<T>(
  path = "",
  options: RequestInit = {}
): Promise<T> {
  const response = await fetch(`${API_URL}${path}`, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...options.headers,
    },
  });

  if (!response.ok) {
    const message = await response.text();
    throw new Error(message || `Request failed: ${response.status}`);
  }

  if (response.status === 204) {
    return undefined as T;
  }

  return response.json() as Promise<T>;
}

export const supplierProductApi = {
  // GET: List rows with supplier and product display information.
  getAll: () => request<SupplierProductDto[]>(),

//   // GET: Get one record by ID.
//   getById: (id: string) =>
//     request<SupplierProduct>(`/${encodeURIComponent(id)}`),

  // POST: Create. The server assigns supplier_product_id.
  create: (supplierProduct: SupplierProductInput) =>
    request<SupplierProduct>("", {
      method: "POST",
      body: JSON.stringify(supplierProduct),
    }),

  // PUT: The record ID is supplied in the URL.
  update: (supplierProduct: SupplierProduct) =>
    request<void>(`/${encodeURIComponent(supplierProduct.supplier_product_id)}`, {
      method: "PUT",
      body: JSON.stringify(supplierProduct),
    }),

  // DELETE: Delete by ID.
  delete: (id: string) =>
    request<void>(`/${encodeURIComponent(id)}`, {
      method: "DELETE",
    }),
};
